    # Insert raw_data first
    for item in raw_data:
        w = item[0].lower().strip()
        if w not in added_words:
            added_words.add(w)
            expansion_list.append({
                "word": w, "ipa": item[1], "pos": item[2],
                "meaning_vi": item[3], "example_sentence": item[4],
                "topic": item[5], "level": item[6], "is_custom": 0
            })

    for topic, words in vocab_catalog.items():
        for item in words:
            w = item[0].lower().strip()
            if w not in added_words:
                added_words.add(w)
                expansion_list.append({
                    "word": w, "ipa": item[1], "pos": item[2],
                    "meaning_vi": item[3], "example_sentence": item[4],
                    "topic": topic, "level": item[5], "is_custom": 0
                })

    print(f"Catalog words count: {len(expansion_list)}")

    # We need to reach exactly 1850 expansion words so that 1000 + 1850 = 2850 total words.
    target_expansion_count = 1850
    needed_more = target_expansion_count - len(expansion_list)
    print(f"Needed more words to reach {target_expansion_count}: {needed_more}")

    # Build the remaining words from genuine Oxford 3000 list
    if needed_more > 0:
        # Load comprehensive Oxford 3000 standard dictionary
        from oxford_base_pool import get_oxford_additional_pool
        additional_pool = get_oxford_additional_pool()
        for item in additional_pool:
            if len(expansion_list) >= target_expansion_count:
                break
            w = item["word"].lower().strip()
            if w not in added_words:
                added_words.add(w)
                expansion_list.append(item)

    print(f"Final expansion words count: {len(expansion_list)}")
    print(f"Total system words will be: {len(existing_words) + len(expansion_list)}")

    out_path = os.path.join("scripts", "oxford_expanded_words.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(expansion_list, f, ensure_ascii=False, indent=2)
    print(f"Saved expansion words to {out_path}")

